import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract watermark high_ts (single row)
    high_ts = watermark["high_ts"].iloc[0]

    # Step 1: keep only events with event_ts > watermark.high_ts
    filtered = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    if filtered.empty:
        return {"new_snapshot": target_snapshot.reset_index(drop=True)}

    # Step 2: per product_id, pick the latest event by (event_ts, event_seq)
    filtered = filtered.sort_values(
        by=["event_ts", "event_seq"], ascending=[True, True]
    )
    latest = filtered.groupby("product_id", as_index=False).tail(1)

    # Build dict of target snapshot rows by product_id for upsert/delete
    snapshot = target_snapshot.set_index("product_id", drop=False)
    snapshot_dict = snapshot.to_dict(orient="index")

    for _, ev in latest.iterrows():
        pid = ev["product_id"]
        op = ev["op"]
        if op == "D":
            if pid in snapshot_dict:
                del snapshot_dict[pid]
        else:
            # I or U: upsert name/price, set last_event_ts = event_ts
            snapshot_dict[pid] = {
                "product_id": pid,
                "name": ev["name"],
                "price": ev["price"],
                "last_event_ts": ev["event_ts"],
            }

    if snapshot_dict:
        result = pd.DataFrame(list(snapshot_dict.values()))
        result = result[["product_id", "name", "price", "last_event_ts"]]
    else:
        result = pd.DataFrame(columns=["product_id", "name", "price", "last_event_ts"])

    return {"new_snapshot": result.reset_index(drop=True)}
